#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section Arc_ZYU_Theorem. Variable R : realType. Variables (C : 'cHG[R]) (Z W V U X Y : 'HG[R]). Hypotheses HZ_on_C : Z \in C; HW_on_C : W \in C; HV_on_C : V \in C; HU_on_C : U \in C; HX_on_C : X \in C; HY_on_C : Y \in C; Hdistinct : uniq [:: Z; W; V; U; X; Y]; Hz_center : center C = Z; Variable x : R; Hypotheses H_WZV : angle_deg W Z V = 4 * x; H_VZU : angle_deg V Z U = 2 * x + 24. Definition arc_measure P Q := angle_deg P Z Q. Lemma compute_x : 4 * x + (2 * x + 24) + arc_measure U X + arc_measure X Y + arc_measure Y W = 360 -> x = 24. Proof. by []. Qed. End Arc_ZYU_Theorem.
